import{_ as o,a0 as i,w as r,s as d,I as e,x as n,a1 as a,A as t,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"關於編譯代碼你應該知道的 | LCTT x X-CMD","titleTemplate":false,"description":"關於編譯代碼你應該知道的 | LCTT (202211) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"關於編譯代碼你應該知道的 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"關於編譯代碼你應該知道的 | LCTT (202211) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202211/20221013 What you need to know about compiling code","title":"關於編譯代碼你應該知道的","tag":"202211","desc":""},"relativePath":"202211/20221013 What you need to know about compiling code.md","filePath":"[post].md"}'),u={name:"202211/20221013 What you need to know about compiling code.md"};function m(g,s,b,f,h,k){const l=i("Link");return r(),d("div",null,[s[29]||(s[29]=e("h1",{id:"關於編譯代碼你應該知道的",tabindex:"-1"},[n("關於編譯代碼你應該知道的 "),e("a",{class:"header-anchor",href:"#關於編譯代碼你應該知道的","aria-label":"Permalink to “關於編譯代碼你應該知道的”"},"​")],-1)),s[30]||(s[30]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202211/04/054126nec50keexencosc4.jpg",alt:""})],-1)),s[31]||(s[31]=e("blockquote",null,[e("p",null,"用這個方便的捕鼠器比喻來理解編譯代碼。")],-1)),e("p",null,[s[1]||(s[1]=n("源代碼必須要經過編譯才能夠運行程序，而對於開源軟件，每個人都可以獲取源代碼。無論你是自己編寫了代碼，想要編譯和運行它，還是下載了某人的項目來嘗試它，瞭解如何通過 ",-1)),a(l,{href:"https://opensource.com/article/19/5/primer-assemblers-compilers-interpreters"},{default:t(()=>[...s[0]||(s[0]=[n("編譯器",-1)])]),_:1}),s[2]||(s[2]=n(" 處理源代碼，以及編譯器如何處理這些代碼，這都很有用。",-1))]),s[32]||(s[32]=p(`<h3 id="創建一個更好的捕鼠器" tabindex="-1">創建一個更好的捕鼠器 <a class="header-anchor" href="#創建一個更好的捕鼠器" aria-label="Permalink to “創建一個更好的捕鼠器”">​</a></h3><p>一般情況我們不會將一個捕鼠器比作電腦，但不管你信不信，它確實與你正在使用的設備（手機或電腦）的 CPU 有一些相似之處。經典的捕鼠器（我説的不是 🐈）有兩種狀態：打開或者釋放。你可以認為 <em>打開</em> 是將捕鼠器設置好準備捕獲老鼠，以及 <em>釋放</em> 是捕鼠器被老鼠觸發。某種意義上來説，捕鼠器就像是一台有鼠標的電腦。你可以想像一下這個代碼，用一種虛構的語言來描述這個過程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if mousetrap == 0 then</span></span>
<span class="line"><span>  There&#39;s a mouse!</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>  There&#39;s no mouse yet.</span></span>
<span class="line"><span>end</span></span></code></pre></div><p>換句話説，你可以基於捕鼠器的狀態發現是否有老鼠（數據）。當然，捕鼠器不是萬無一失的，有可能有一隻老鼠在捕鼠器旁邊，由於老鼠還沒有觸發捕鼠器，所以它的狀態還是 <em>打開</em> 的。因此該程序可以進行改進，這都是非常典型的。</p><h3 id="開關" tabindex="-1">開關 <a class="header-anchor" href="#開關" aria-label="Permalink to “開關”">​</a></h3><p>總的來説，捕鼠器就是一個開關。你會在家裏使用開關打開燈。可以從開關中獲得許多信息。比如，人們會從你家燈的狀態瞭解到你是否在家。</p><p>你可以根據鄰居家燈的狀態來改變行為。如果鄰居家所有的燈都熄滅了，那麼請關掉你大聲的音樂，因為人們可能已經上牀睡覺了。</p><p>CPU 也使用這樣的邏輯，只不過乘以幾個數量級，縮小到了微觀級別。當 CPU 在特定寄存器上接收到電信號時，可以觸發其他一些寄存器，然後觸發另一個，以此類推。如果這些寄存器有特定的意義，那麼就可以通信。也許激活同一主板上某處的芯片，或者使 LED 亮起，或者改變屏幕上的像素顏色。</p><p>種瓜得瓜，種豆得豆。如果你真的想在多個位置而不是僅限於一處發現老鼠，但是你只有一個捕鼠器，那你應該開發一個應用才行。使用網絡攝像頭和一些基本的圖像識別軟件，你可以建立空廚房的模型，然後掃描變化。當老鼠進入廚房，在原先沒有老鼠的圖像上會有像素的變化。記錄下這些數據，如果有無人機可以追蹤老鼠並捕獲會更好，這樣就可以將老鼠趕出廚房了。這時，你通過打開和關閉信號的魔法，創造了一個更好的捕鼠器。</p><h3 id="編譯器" tabindex="-1">編譯器 <a class="header-anchor" href="#編譯器" aria-label="Permalink to “編譯器”">​</a></h3><p>代碼編譯器將人們可閲讀的代碼轉換成 CPU 可以理解的機器語言。這是非常複雜的過程，因為 CPU 非常複雜（甚至比捕鼠器更加複雜），同時因為該過程比嚴格“需要”的更加靈活。並不是所有的編譯器都很靈活。有一些編譯器只有一個目標，它們只會處理特定格式的代碼文件，處理過程也因此而簡單明瞭。</p>`,11)),e("p",null,[s[4]||(s[4]=n("幸運的是，現代的通用編譯器並不簡單。它們允許你編寫不同語言的代碼，也允許你用不同的方式鏈接庫文件，並且可以生成運行在不同架構上的文件。",-1)),a(l,{href:"https://opensource.com/article/22/5/gnu-c-compiler"},{default:t(()=>[...s[3]||(s[3]=[n("GNU 編譯器集合",-1)])]),_:1}),s[5]||(s[5]=n("（GCC）的 ",-1)),s[6]||(s[6]=e("code",null,"gcc",-1)),s[7]||(s[7]=n(" 編譯器 ",-1)),s[8]||(s[8]=e("code",null,"--help",-1)),s[9]||(s[9]=n(" 會輸出超過 50 行的選項，LLVM 的 ",-1)),s[10]||(s[10]=e("code",null,"clang",-1)),s[11]||(s[11]=n(" 編譯器的 ",-1)),s[12]||(s[12]=e("code",null,"--help",-1)),s[13]||(s[13]=n(" 輸出超過 1000 行。GCC 指導手冊的字數超過 10 萬。",-1))]),s[33]||(s[33]=p(`<p>當你在編譯代碼時會有很多選項。</p><p>當然，大多數人並不需要知道所有的選項。我從未讀過 GCC 的手冊頁，因為它們是針對 Objective-C、Fortran 以及我從未聽説過的芯片架構的。不過我重視它將代碼編譯為不同的架構 —— 64 位或者 32 位 —— 的能力，以及在其他行業已經落後的計算機上運行開源軟件的能力。</p><h3 id="編譯生命週期" tabindex="-1">編譯生命週期 <a class="header-anchor" href="#編譯生命週期" aria-label="Permalink to “編譯生命週期”">​</a></h3><p>同樣重要的是，理解編譯代碼的不同階段。這是一個簡單的 C 語言程序的生命週期：</p><ol><li>帶有宏定義的 C 源代碼 <code>.c</code> 文件，用 <code>cpp</code> 預處理為 <code>.i</code> 文件。</li><li>擴展了宏定義的 C 源代碼 <code>.i</code> 文件，會被 <code>gcc</code> 轉譯成 <code>.s</code> 文件。</li><li>以彙編語言寫的文本文件 <code>.s</code> 文件被彙編為目標 <code>.o</code> 文件。</li><li>帶有 CPU 指令的二進制目標代碼，以及其他目標文件和庫 <code>*.o</code> 文件，以內存區域無關的偏移量，使用 <code>ld</code> 鏈接以生成可執行文件。</li><li>最終的二進制文件要麼包含所有需要的目標，要麼設置以動態鏈接庫 <code>*.so</code> 文件加載。</li></ol><p>你可以試試這個簡單示例（可能需要對庫路徑做一些調整）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat &lt;&lt; EOF &gt;&gt; hello.c</span></span>
<span class="line"><span> #include</span></span>
<span class="line"><span> int main(void)</span></span>
<span class="line"><span> { printf(&quot;hello world\\n&quot;);</span></span>
<span class="line"><span>   return 0; }</span></span>
<span class="line"><span>   EOF</span></span>
<span class="line"><span>$ cpp hello.c &gt; hello.i</span></span>
<span class="line"><span>$ gcc -S hello.i</span></span>
<span class="line"><span>$ as -o hello.o hello.s</span></span>
<span class="line"><span>$ ld -static -o hello \\</span></span>
<span class="line"><span>  -L/usr/lib64/gcc/x86_64-slackware-linux/5.5.0/ \\</span></span>
<span class="line"><span>  /usr/lib64/crt1.o /usr/lib64/crti.o hello.o \\</span></span>
<span class="line"><span>  /usr/lib64/crtn.o  --start-group -lc -lgcc \\</span></span>
<span class="line"><span>  -lgcc_eh --end-group</span></span>
<span class="line"><span>$ ./hello</span></span>
<span class="line"><span>hello world</span></span></code></pre></div><h3 id="可獲得的知識" tabindex="-1">可獲得的知識 <a class="header-anchor" href="#可獲得的知識" aria-label="Permalink to “可獲得的知識”">​</a></h3><p>計算機已經變得非常強大，並且用户友好。請不要走向這兩種可能的極端中的任何一種：計算機不像捕鼠器和電燈開關那麼簡單，但它們也不是無法理解的。你可以瞭解編譯代碼、如何鏈接以及針對不同架構進行編譯。一旦你知道了，你就可以更好地調試代碼。你可以理解你下載的代碼，甚至可以修復其中的一兩個錯誤。同時從理論上來講，你可以建造一個更好的捕鼠器，或者用捕鼠器造一個 CPU。由你決定。</p><hr>`,10)),e("p",null,[s[15]||(s[15]=n("via: ",-1)),a(l,{href:"https://opensource.com/article/22/10/compiling-code"},{default:t(()=>[...s[14]||(s[14]=[n("https://opensource.com/article/22/10/compiling-code",-1)])]),_:1})]),e("p",null,[s[20]||(s[20]=n("作者：",-1)),a(l,{href:"https://opensource.com/users/alansmithee"},{default:t(()=>[...s[16]||(s[16]=[n("Alan Smithee",-1)])]),_:1}),s[21]||(s[21]=n(" 選題：",-1)),a(l,{href:"https://github.com/lkxed"},{default:t(()=>[...s[17]||(s[17]=[n("lkxed",-1)])]),_:1}),s[22]||(s[22]=n(" 譯者：",-1)),a(l,{href:"https://github.com/Donkey-Hao"},{default:t(()=>[...s[18]||(s[18]=[n("Donkey-Hao",-1)])]),_:1}),s[23]||(s[23]=n(" 校對：",-1)),a(l,{href:"https://github.com/wxy"},{default:t(()=>[...s[19]||(s[19]=[n("wxy",-1)])]),_:1})]),e("p",null,[s[26]||(s[26]=n("本文由 ",-1)),a(l,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[24]||(s[24]=[n("LCTT",-1)])]),_:1}),s[27]||(s[27]=n(" 原創編譯，",-1)),a(l,{href:"https://linux.cn/"},{default:t(()=>[...s[25]||(s[25]=[n("Linux中國",-1)])]),_:1}),s[28]||(s[28]=n(" 榮譽推出",-1))])])}const x=o(u,[["render",m]]);export{T as __pageData,x as default};
